class FileHandle {
  FILE* fp;
public:
  explicit FileHandle(const char* path) : fp(fopen(path, "r")) {}
  ~FileHandle() { if (fp) fclose(fp); }
  FileHandle(const FileHandle&) = delete;            // non-copyable
  FileHandle& operator=(const FileHandle&) = delete;
};
void use() {
  FileHandle f("data.bin");   // acquired here
  // ... even if this throws, ~FileHandle() still runs
}                              // released here

class Buffer {
  size_t n; int* data;
public:
  Buffer(Buffer&& o) noexcept : n(o.n), data(o.data) {
    o.data = nullptr; o.n = 0;   // steal, don't copy
  }
  Buffer& operator=(Buffer&& o) noexcept {
    if (this != &o) { delete[] data; data = o.data; n = o.n; o.data = nullptr; o.n = 0; }
    return *this;
  }
};

